const BASE = 'https://k257603.app.n8n.cloud/webhook/pla-demo-7f3k9q2m';

const q = $('Dashboard Request').first().json.query || {};
const sellerQ = String(q.seller_id || '').trim().toUpperCase();
const runQ = String(q.run_id || '').trim();

function rows(name) {
  return $(name).all().map(i => i.json)
    .filter(r => r && r.run_id === runQ && r.seller_id === sellerQ);
}

function esc(v) {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function parse(v, fallback) {
  if (v && typeof v === 'object') return v;
  try { return JSON.parse(v || ''); }
  catch { return fallback; }
}

// Exact integer-paisa formatting, without floating-point math.
function pkr(v) {
  if (v === null || v === undefined || v === '') return 'Unknown';
  const s = String(v);
  if (!/^-?\d+$/.test(s)) return 'Unknown';

  const negative = s.startsWith('-');
  const digits = (negative ? s.slice(1) : s)
    .replace(/^0+(?=\d)/, '');

  const padded = digits.padStart(3, '0');
  const whole = padded.slice(0, -2)
    .replace(/\B(?=(\d{3})+(?!\d))/g, ',');

  return (negative && !/^0+$/.test(digits) ? '-' : '') +
    'PKR ' + whole + '.' + padded.slice(-2);
}

