function badge(v) {
  const s = String(v ?? 'UNKNOWN').toUpperCase();

  const good = ['SETTLED','COMPLETED','OK','CONFIRMED'];
  const bad = ['FAILED','OVERSETTLED','OVERDUE',
    'MISMATCH','HIGH','CONFLICT'];
  const warn = ['UNKNOWN','PARTIALLY_SETTLED','UNSETTLED',
    'PROVISIONAL','MEDIUM'];

  const cls = good.includes(s) ? 'good' :
    bad.includes(s) ? 'bad' :
    warn.includes(s) ? 'warn' : '';

  return '<span class="badge ' + cls + '">' +
    esc(s.replace(/_/g,' ')) + '</span>';
}

function page(title, body, statusCode = 200) {
  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<title>${esc(title)}</title>
${css}
</head>
<body>
<main class="container">
<header class="header">
<div class="brand">
<div class="logo">◇</div>
<div>
<div class="brand-title">Profit Leak Analyzer</div>
<div class="subtitle">Financial Reconciliation Dashboard</div>
</div>
</div>
${badge('PRIVATE DEMO')}
</header>
${body}
<footer class="footer">
Private demo · Synthetic test data only ·
No authentication · Not production-ready
</footer>
</main>
</body>
</html>`;

  return [{ json: {
    status_code: statusCode,
    body: html
  }}];
}

const banner = `
<div class="notice warning">
<strong>Private synthetic-data demo.</strong>
This dashboard has no authentication. Anyone with a valid
seller ID and run ID can access its data.
Do not upload real seller or customer information.
</div>`;

function errorPage(title, message, code) {
  return page(title, banner + `
  <div class="card hero">
    <div>
      <h1>${esc(title)}</h1>
      <p class="muted">${esc(message)}</p>
    </div>
    ${badge('UNAVAILABLE')}
  </div>`, code);
}

// Validate request and run ownership
if (!sellerQ || !runQ) {
  return errorPage(
    'Missing report information',
    'Provide seller_id and run_id in the URL.',
    400
  );
}

const run = rows('Lookup Run')[0];

if (!run) {
  return errorPage(
    'Run not found',
    'No analysis exists for the specified seller and run.',
    404
  );
}

if (run.status !== 'COMPLETED') {
  return errorPage(
    'Analysis unavailable',
    'This run has not completed successfully. No financial figures are shown.',
    409
  );
}

// Read original stored data
const k = parse(run.kpis_json, {});
const coverage = parse(run.coverage_json, []);
const rules = parse(run.rules_json, []);
const mapping = parse(run.mapping_json, {});
const warnings = parse(run.warnings_json, {});

function sortedRows(name) {
  return rows(name).sort((a,b) =>
    Number(a.seq || 0) - Number(b.seq || 0)
  );
}

const res = sortedRows('Load Results');
const exc = sortedRows('Load Exceptions');
const ver = sortedRows('Load Validation Errors');
const stl = sortedRows('Load Settlements');

// Preserve persistence integrity checks
const checks = [
  [res.length, run.results_count],
  [exc.length, run.exceptions_count],
  [ver.length, run.validation_errors_count],
  [stl.length, run.settlement_summary_count]
];

if (!checks.every(c => Number(c[0]) === Number(c[1]))) {
  return errorPage(
    'Report temporarily unavailable',
    'Stored record counts do not match the completed analysis. Financial results are withheld.',
    409
  );
}

const exportUrl = type =>
  BASE + '/export?seller_id=' +
  encodeURIComponent(run.seller_id) +
  '&run_id=' + encodeURIComponent(run.run_id) +
  '&type=' + type;

function metric(label, key, note = '', primary = false) {
  return `
  <div class="card kpi ${primary ? 'primary' : ''}">
    <div class="kpi-label">${esc(label)}</div>
    <div class="kpi-value">${esc(pkr(k[key]))}</div>
    ${note ? `<div class="kpi-note">${esc(note)}</div>` : ''}
  </div>`;
}

function countMetric(label, count) {
  return `
  <div class="card kpi">
    <div class="kpi-label">${esc(label)}</div>
    <div class="kpi-value">${esc(count)}</div>
  </div>`;
}

function section(title, content, subtitle = '') {
  return `
  <section class="section">
    <div class="section-head">
      <h2>${esc(title)}</h2>
      <span class="muted">${esc(subtitle)}</span>
    </div>
    ${content}
  </section>`;
}

function table(headers, items, render, limit = 300) {
  const visible = items.slice(0, limit);

  let html = `
  <div class="table-wrap">
  <table>
    <thead><tr>
      ${headers.map(h => `<th>${esc(h)}</th>`).join('')}
    </tr></thead>
    <tbody>`;

  if (!visible.length) {
    html += `<tr>
      <td colspan="${headers.length}" class="empty">
        No records to display
      </td>
    </tr>`;
  } else {
    html += visible.map(item => `
      <tr>
        ${render(item).map(v => `<td>${v}</td>`).join('')}
      </tr>
    `).join('');
  }

  html += '</tbody></table></div>';

  if (items.length > limit) {
    html += `<p class="muted">
      Showing ${limit} of ${items.length} records.
      Download CSV for the complete dataset.
    </p>`;
  }

  return html;
}

function statusPanel(title, counts) {
  const entries = Object.entries(counts || {});

  return `
  <div class="card panel">
    <h3>${esc(title)}</h3>
    ${entries.length ? entries.map(([name,n]) => `
      <div class="status-row">
        ${badge(name)}
        <strong>${esc(n)}</strong>
      </div>`).join('') :
      '<p class="muted">No data available</p>'}
  </div>`;
}

let h = banner;

// Header and export actions
h += `
<div class="card hero">
  <div>
    <h1>Reconciliation overview</h1>
    <div class="meta">
      <strong>Seller:</strong> ${esc(run.seller_id)} &nbsp;·&nbsp;
      <strong>As of:</strong> ${esc(run.as_of_date)}
    </div>
    <div class="meta">
      <strong>Run:</strong> ${esc(run.run_id)} &nbsp;·&nbsp;
      <strong>Engine:</strong> ${esc(run.engine_version)}
    </div>
    <div class="meta">Completed: ${esc(run.completed_at)}</div>
  </div>
  <div class="actions">
    <a class="button" href="${esc(exportUrl('results'))}">
      &#8595; Export results
    </a>
    <a class="button secondary" href="${esc(exportUrl('exceptions'))}">
      &#8595; Exceptions
    </a>
    <a class="button secondary" href="${esc(exportUrl('validation'))}">
      &#8595; Validation
    </a>
  </div>
</div>`;

// Financial metrics
h += section('Receivables & cash', `
  <div class="grid">
    ${metric('Expected receivables','expected_receivable_paisa')}
    ${metric('Verified payments','verified_paid_paisa',
      'Includes adjustments once',true)}
    ${metric('Outstanding receivables','outstanding_receivable_paisa',
      'Not automatically a loss')}
    ${metric('Net settlement variance','net_settlement_variance_paisa',
      'Signed amount')}
    ${metric('Overpaid','overpaid_paisa')}
    ${metric('Cash adjustments','adjustment_paisa',
      'Already included in verified payments')}
    ${metric('Overdue — confirmed','overdue_receivable_confirmed_paisa')}
    ${metric('Overdue — provisional','overdue_receivable_provisional_paisa',
      'User-declared coverage')}
  </div>`);

// Operational metrics
h += section('Fees, returns & exposure', `
  <div class="grid">
    ${metric('Verified fee discrepancy','verified_fee_discrepancy_paisa')}
    ${metric('RTO fee discrepancy','rto_fee_discrepancy_paisa')}
    ${metric('RTO operational costs','rto_operational_cost_paisa',
      'Separate from receivables')}
    ${metric('Unallocated settlement','unallocated_settlement_paisa')}
    ${metric('Unattributed batch fees','unattributed_fee_paisa')}
    ${metric('Potential exposure','potential_exposure_paisa',
      'Informational only')}
    ${countMetric('Exceptions',exc.length)}
    ${countMetric('Validation errors',ver.length)}
  </div>`);

h += `
<div class="notice info">
  <strong>Important:</strong> Financial discrepancies, outstanding
  receivables, RTO costs and potential exposure are separate
  categories. They must not be added into a single loss amount.
  User-declared settlement coverage is not independently verified.
</div>`;

// Independent status breakdowns
h += section('Settlement health', `
  <div class="grid two">
    ${statusPanel('Settlement completeness',
      k.counts_by_completeness)}
    ${statusPanel('Due-date status',
      k.counts_by_due_date_status)}
  </div>`);

// Shipment table
h += section('Shipment reconciliation',
  table(
    ['Shipment / Order','Courier','Delivery','Settlement',
     'Due date','Expected','Verified','Outstanding','Overpaid'],
    res,
    r => [
      `<strong>${esc(r.shipment_id || '—')}</strong>
       <span class="small">${esc(r.order_id || 'No order')}</span>`,
      esc(r.courier),
      esc(r.normalized_status),
      badge(r.settlement_completeness),
      badge(r.due_date_status) +
        (r.due_date_confidence ?
          `<span class="small">${esc(r.due_date_confidence)}</span>` : ''),
      esc(pkr(r.expected_receivable_paisa)),
      esc(pkr(r.verified_paid_paisa)),
      esc(pkr(r.outstanding_receivable_paisa)),
      esc(pkr(r.overpaid_paisa))
    ],
    200
  ),
  `${res.length} results`
);

// Exceptions table with expandable evidence
h += section('Exceptions & investigation',
  table(
    ['Type','Severity','Confidence','Reference',
     'Amount','Description / Evidence'],
    exc,
    x => [
      badge(x.type),
      badge(x.severity),
      badge(x.confidence),
      esc(x.shipment_id || x.settlement_id ||
        x.order_id || x.tracking_number || '—'),
      esc(pkr(x.amount_paisa)),
      `<div>${esc(x.description)}</div>` +
        (x.evidence_json ?
          `<details>
            <summary>View evidence</summary>
            <pre>${esc(JSON.stringify(
              parse(x.evidence_json,{}),null,2
            ))}</pre>
          </details>` : '')
    ]
  ),
  `${exc.length} findings`
);

// Settlement entries
h += section('Settlement entries',
  table(
    ['Settlement','Courier','Type','Net paid',
     'Allocated','Unallocated','Arithmetic'],
    stl,
    s => [
      esc(s.settlement_id),
      esc(s.courier),
      badge(s.entry_type),
      esc(pkr(s.net_paid_paisa)),
      esc(pkr(s.allocated_paisa)),
      esc(pkr(s.unallocated_paisa)),
      badge(
        s.arithmetic_ok === true || s.arithmetic_ok === 'true'
          ? 'OK'
          : s.arithmetic_ok === null ||
            s.arithmetic_ok === undefined
            ? 'NOT_APPLICABLE' : 'MISMATCH'
      )
    ]
  ),
  `${stl.length} entries`
);

// Validation errors
h += section('Validation & data quality',
  table(
    ['Source','Row','Field','Code','Level','Raw value','Message'],
    ver,
    v => [
      esc(v.source),
      esc(v.row_number),
      esc(v.field),
      badge(v.code),
      badge(v.level),
      esc(v.raw_value),
      esc(v.message)
    ]
  ),
  `${ver.length} errors`
);

// Audit and configuration
h += section('Audit & input configuration', `
  <div class="card panel">
    <p class="muted">
      <strong>Output hash:</strong> ${esc(run.output_hash)}
    </p>
    <p class="muted">
      <strong>Run key:</strong> ${esc(run.run_key)}
    </p>
    <details>
      <summary>Courier rules</summary>
      <pre>${esc(JSON.stringify(rules,null,2))}</pre>
    </details>
    <details>
      <summary>Settlement coverage</summary>
      <pre>${esc(JSON.stringify(coverage,null,2))}</pre>
    </details>
    <details>
      <summary>Column mapping</summary>
      <pre>${esc(JSON.stringify(mapping,null,2))}</pre>
    </details>
    <details>
      <summary>Warnings and import notes</summary>
      <pre>${esc(JSON.stringify(warnings,null,2))}</pre>
    </details>
  </div>
`);

return page('Profit Leak Analyzer – ' + run.seller_id, h, 200);

// ---- Build CSV export ----
const q = $('Export Request').first().json.query || {};
const sellerQ = String(q.seller_id || '').trim().toUpperCase();
const runQ = String(q.run_id || '').trim();
const type = String(q.type || '');
function err(code, msg) { return [{ json: { status_code: code, content_type: 'text/plain; charset=utf-8', disposition: '', body: msg } }]; }
const COLS = {
  results: ['seq', 'order_id', 'shipment_id', 'tracking_number', 'courier', 'normalized_status', 'settlement_completeness', 'due_date_status', 'due_date_confidence', 'expected_receivable_paisa', 'verified_paid_paisa', 'outstanding_receivable_paisa', 'overpaid_paisa', 'result_json'],
  exceptions: ['seq', 'exception_id', 'type', 'severity', 'confidence', 'order_id', 'shipment_id', 'tracking_number', 'settlement_id', 'amount_paisa', 'description', 'evidence_json'],
  validation: ['seq', 'source', 'row_number', 'field', 'code', 'level', 'message', 'raw_value'],
};
if (!sellerQ || !runQ) return err(400, 'seller_id and run_id are required');
if (!COLS[type]) return err(400, 'type must be results, exceptions or validation');
if (!/^[A-Za-z0-9_-]{1,80}$/.test(runQ)) return err(400, 'invalid run_id');
const run = $('Lookup Export Run').all().map(function (i) { return i.json; }).find(function (r) { return r && r.run_id === runQ && r.seller_id === sellerQ; });
if (!run) return err(404, 'run not found for this seller');
if (run.status !== 'COMPLETED') return err(409, 'run is ' + run.status + '; exports are only available for COMPLETED runs');
const src = { results: 'Load Result Rows', exceptions: 'Load Exception Rows', validation: 'Load Validation Rows' }[type];
const data = $(src).all().map(function (i) { return i.json; }).filter(function (r) { return r && r.run_id === runQ && r.seller_id === sellerQ; }).sort(function (a, b) { return a.seq - b.seq; });
const expected = Number({ results: run.results_count, exceptions: run.exceptions_count, validation: run.validation_errors_count }[type]);
if (data.length !== expected) return err(500, 'stored row count ' + data.length + ' does not match run record ' + expected + '; export refused');
function cell(v) {
  let s = v === null || v === undefined ? '' : String(v);
  if (/^[=+\-@\t\r]/.test(s) && !/^-?\d+(\.\d+)?$/.test(s)) s = "'" + s; // neutralise spreadsheet formulas, keep negative numbers
  return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
